var a = [29, 10, 14, 37, 13];
for (var i = 0; i < a.length - 1; i++) {
  var min = i;
  for (var j = i + 1; j < a.length; j++) {
    if (a[j] < a[min]) {
      min = j;
    }
  }
  var temp = a[i];
  a[i] = a[min];
  a[min] = temp;
}
console.log(a);
